use crate::header::generated_header;
use pretty_assertions::assert_eq;

#[test]
fn the_leading_comment_of_a_generator_marks_a_file_in_the_comment_syntax_of_its_language() {
  for (path, text, line) in [
    // the outputs of a renderer: an HTML comment in Markdown, a `#` comment of a rules file
    (
      "AGENTS.md",
      "<!-- Generated by community/.ai/render-guides.mjs; edit community/.ai/* -->\n\n## Project Invariants\n",
      "Generated by community/.ai/render-guides.mjs; edit community/.ai/*",
    ),
    (
      ".codex/rules/default.rules",
      "# Generated from community/.ai/tool-permissions.json by community/.ai/render-guides.mjs.\n# Edit the source list and rerun the renderer; do not edit this file by hand.\n",
      "Generated from community/.ai/tool-permissions.json by community/.ai/render-guides.mjs.",
    ),
    // Go's convention, a doc comment of Rust, a block comment of Kotlin over several lines, `@generated`
    (
      "api/api.pb.go",
      "// Code generated by protoc-gen-go. DO NOT EDIT.\n\npackage api\n",
      "Code generated by protoc-gen-go. DO NOT EDIT.",
    ),
    (
      "src/bindings.rs",
      "//! This file is generated by specta\nuse serde::Serialize;\n",
      "This file is generated by specta",
    ),
    (
      "src/Bodies.kt",
      "/*\n * Copyright 2026 the authors\n * Auto-generated by AirAuthored, do not edit\n */\npackage air\n",
      "Auto-generated by AirAuthored, do not edit",
    ),
    ("lib/schema.ts", "// @generated SignedSource<<abc>>\nexport type A = 1\n", "@generated SignedSource<<abc>>"),
    // a shebang, a front matter of Markdown and blank lines come first
    ("tools/gen.sh", "#!/bin/sh\n# Generated by make-tools\necho\n", "Generated by make-tools"),
    (
      "skills/a/SKILL.md",
      "---\nname: a\ndescription: b\n---\n\n<!-- Generated by render.mjs -->\n# A\n",
      "Generated by render.mjs",
    ),
    ("config.toml", "\n\n# generated by the renderer\nkey = 1\n", "generated by the renderer"),
  ] {
    assert_eq!(generated_header(path, text).as_deref(), Some(line), "{path}");
  }
}

#[test]
fn a_hand_kept_file_that_mentions_a_generator_is_no_generated_file() {
  for (path, text) in [
    // the line Cargo writes into the `.gitignore` it starts, which people keep
    (".gitignore", "# Generated by Cargo\n/target\n"),
    // `generated` in the middle of a sentence of a doc comment
    (
      "src/registry_test.rs",
      "//! The commands of the registry are the ones generated from the same for_each_command!\nuse a::b;\n",
    ),
    // a heading of Markdown is no comment
    ("docs/guide.md", "# Generated Files\n\nWhat a tool writes.\n"),
    // a marker after the fifth comment line, after the code, or in a string
    ("src/a.rs", "// 1\n// 2\n// 3\n// 4\n// 5\n// Generated by x\n"),
    ("src/b.rs", "fn main() {}\n// Generated by x\n"),
    ("src/c.ts", "const note = \"Generated by x\"\n"),
    // JSON has no comments, and a comment of another syntax is none
    ("config/mcp.json", "{\"_comment\": \"Generated by x\"}\n"),
    ("src/d.kt", "# Generated by x\nclass D\n"),
    ("README.md", "// Generated by x\n"),
  ] {
    assert_eq!(generated_header(path, text), None, "{path}");
  }
}
